# те же черты под другим английским названием в V20 — охотник видит общую
ALIASES = {"poor eyesight": "bad sight", "deafness": "deaf"}


def _span(cost):
    """«2» → (2, 2); «1–3» → (1, 3); «2/4» — одно из двух → (2, 4)."""
    a, *b = cost.replace("–", "/").split("/")
    return int(a), int(b[-1]) if b else int(a)


def collect(existing):
    """Записи для data/merits.json (линия «hunter»; черты Свидетелей — с пометкой bystander). Черты, которые у охотника уже есть в общем списке V20
    (то же английское название, без эпохи, клана, секты и линии), не дублируются — охотник видит общую."""
    seen = {m["en"].lower() for m in existing if m.get("en") and not (m.get("era") or m.get("clan") or m.get("sect") or m.get("line"))}
    out = []
    rows_all = [(kind, r, False) for kind, rows in (("merit", MERITS), ("flaw", FLAWS)) for r in rows]
    rows_all += [(kind, (en, name, cat, cost, text), True) for en, name, kind, cat, cost, text in BYSTANDER]
    for kind, (en, name, cat, cost, text), lost in rows_all:
        if not lost and ALIASES.get(en.lower(), en.lower()) in seen:    # Haunted и Hunted Свидетеля — не те, что в V20
            continue
        lo, hi = _span(cost)
        out.append({"kind": kind, "category": cat, "name": name, "en": en, "cost": cost, "min": lo, "max": hi,
                    "clan": "", "sect": "", "era": "", "source": SRC, "line": "hunter",
                    "html": f"<p><em>Источник: {SRC} (пересказ).</em></p><p>{text}</p>", **({"bystander": True} if lost else {})})
    return out
